'use strict';
// Technology: nations research one project at a time with points generated by
// education, literacy and the size of the economy. Each technology gives
// specific bonuses: building productivity, army strength, corruption, etc.
//
// c.research = { current: techId|null, progress, done: [techIds] }

const TECHS = {
  // Industry
  assembly: { name: 'Assembly Lines', cat: 'Industry', cost: 120, req: [], desc: '+12% output from all factories.', prod: { Industry: 0.12 } },
  petrochem: { name: 'Petrochemicals', cat: 'Industry', cost: 200, req: ['assembly'], desc: '+25% refinery output, +10% appliance output.', prodB: { refinery: 0.25, applianceFactory: 0.1 } },
  electronics: { name: 'Electronics', cat: 'Industry', cost: 300, req: ['assembly'], desc: '+30% appliance output, +10% arms output.', prodB: { applianceFactory: 0.3, armsFactory: 0.1 } },
  automation: { name: 'Automation', cat: 'Industry', cost: 380, req: ['petrochem', 'electronics'], desc: '+15% output from all factories.', prod: { Industry: 0.15 } },
  // Land
  mechFarming: { name: 'Mechanized Farming', cat: 'Land', cost: 120, req: [], desc: '+15% output from farms, ranches and plantations.', prod: { Agriculture: 0.15 } },
  deepMining: { name: 'Deep Mining', cat: 'Land', cost: 160, req: [], desc: '+20% output from mines, wells, logging and fishing.', prod: { Extraction: 0.2 } },
  fertilizers: { name: 'Chemical Fertilizers', cat: 'Land', cost: 220, req: ['mechFarming'], desc: '+20% grain and fiber output.', prodB: { farm: 0.2, plantation: 0.2 } },
  highYield: { name: 'High-Yield Crops', cat: 'Land', cost: 340, req: ['fertilizers'], desc: '+20% agricultural output; peasants grow 25% more food.', prod: { Agriculture: 0.2 }, subsist: 0.25 },
  // Society
  massLiteracy: { name: 'Mass Literacy', cat: 'Society', cost: 120, req: [], desc: 'Literacy rises 10 points higher.', literacy: 0.1 },
  publicHealth: { name: 'Public Health', cat: 'Society', cost: 160, req: [], desc: 'Faster population growth and fewer deaths from hunger.', popGrowth: 0.0004 },
  broadcasting: { name: 'Broadcasting', cat: 'Society', cost: 220, req: ['massLiteracy'], desc: '+2 approval; propaganda is 50% more effective.', approval: 2 },
  socialInsurance: { name: 'Social Insurance', cat: 'Society', cost: 280, req: ['publicHealth'], desc: '+6 worker loyalty and +2 approval.', workers: 6, approval: 2 },
  // Military
  mechInfantry: { name: 'Mechanized Infantry', cat: 'Military', cost: 140, req: [], desc: '+12% army strength.', strength: 0.12 },
  defenseDepth: { name: 'Defense in Depth', cat: 'Military', cost: 180, req: [], desc: 'Our armies are 25% stronger when defending.', defense: 0.25 },
  airPower: { name: 'Air Power', cat: 'Military', cost: 260, req: ['mechInfantry'], desc: '+15% army strength.', strength: 0.15 },
  missiles: { name: 'Guided Missiles', cat: 'Military', cost: 380, req: ['airPower', 'electronics'], desc: '+18% army strength.', strength: 0.18 },
  // Statecraft
  civilService: { name: 'Civil Service Reform', cat: 'Statecraft', cost: 140, req: [], desc: '−6 corruption, +0.2 political capital per month.', corruption: -6, pc: 0.2 },
  statistics: { name: 'National Statistics', cat: 'Statecraft', cost: 200, req: ['civilService'], desc: '+5% tax revenue.', taxEff: 0.05 },
  publicRelations: { name: 'Public Relations', cat: 'Statecraft', cost: 240, req: ['broadcasting'], desc: '+0.3 political capital per month and +1 approval.', pc: 0.3, approval: 1 },
};
const TECH_KEYS = Object.keys(TECHS);
const TECH_CATS = ['Industry', 'Land', 'Society', 'Military', 'Statecraft'];

function ensureResearch(c) {
  if (!c.research) c.research = { current: null, progress: 0, done: [] };
  return c.research;
}

function hasTech(c, id) { return !!(c.research && c.research.done.includes(id)); }

function techAvailable(c, id) {
  const R = ensureResearch(c);
  return !R.done.includes(id) && TECHS[id].req.every(r => R.done.includes(r));
}

// Sum a numeric field across every researched technology.
function techSum(c, field) {
  let s = 0;
  if (!c.research) return 0;
  for (const id of c.research.done) s += TECHS[id][field] || 0;
  return s;
}

// Output multiplier for a building type.
function techProd(c, buildingType) {
  if (!c.research) return 1;
  const kind = BUILDINGS[buildingType].kind;
  let m = 1;
  for (const id of c.research.done) {
    const T = TECHS[id];
    if (T.prod && T.prod[kind]) m += T.prod[kind];
    if (T.prodB && T.prodB[buildingType]) m += T.prodB[buildingType];
  }
  return m;
}

function researchRate(c) {
  const lit = c.econ ? c.econ.literacy : 0.3;
  // University graduates speed research (ideas.js).
  // Famous inventors speed research in their field (figures.js).
  return (0.6 + c.policy.education * lit * Math.pow(Math.max(c.gdp, 0.1), 0.35) * 0.9) * (1 + (c.uni || 0) * 3) * (1 + (typeof inventorBonus === 'function' ? inventorBonus(c) : 0));
}

const TECH_TASTE = {
  democracy: { Society: 1.5, Statecraft: 1.2 }, constMonarchy: { Society: 1.2, Industry: 1.2 }, absMonarchy: { Land: 1.4, Military: 1.2 },
  junta: { Military: 2 }, communist: { Industry: 1.8, Society: 1.2 }, fascist: { Military: 2.2, Industry: 1.3 }, theocracy: { Land: 1.5, Statecraft: 1.2 },
};

function tickResearch(game, c) {
  const R = ensureResearch(c);
  if (!R.current || !techAvailable(c, R.current)) {
    R.current = null;
    if (isPlayer(game, c)) { R.idle = (R.idle || 0) + 1; return; }
    const opts = TECH_KEYS.filter(id => techAvailable(c, id));
    if (!opts.length) return;
    const taste = TECH_TASTE[c.gov] || {};
    R.current = game.rng.weighted(opts, id => (taste[TECHS[id].cat] || 1) * (typeof inventorPull === 'function' ? inventorPull(c, TECHS[id].cat) : 1) / TECHS[id].cost);
  }
  R.progress += researchRate(c);
  const T = TECHS[R.current];
  if (R.progress >= T.cost) {
    R.progress -= T.cost;
    R.done.push(R.current);
    logNews(game, `${c.name} develops ${T.name}.`, 'tech', [c.id]);
    if (isPlayer(game, c)) toastPlayer(game, `Research complete: ${T.name}. ${T.desc}`, 'good');
    R.current = null;
  }
}

function setResearch(game, id) {
  const c = game.countries[game.player];
  if (!techAvailable(c, id)) return { ok: false, msg: 'Not available yet.' };
  const R = ensureResearch(c);
  if (R.current && R.current !== id) R.progress *= 0.5; // switching projects wastes half the work
  R.current = id;
  R.idle = 0;
  return { ok: true, msg: `Our scientists turn to ${TECHS[id].name}.` };
}
